9	 if(typeof a==='string'&&typeof z==='string'){let lo=0,hi=0;while(lo<a.length&&lo<z.length&&a[lo]===z[lo])lo++;while(hi<a.length-lo&&hi<z.length-lo&&a[a.length-hi-1]===z[z.length-hi-1])hi++;return [{path:p,common_prefix_chars:lo,common_suffix_chars:hi,before_changed:a.slice(lo,a.length-hi),after_changed:z.slice(lo,z.length-hi),prefix_context:a.slice(Math.max(0,lo-50),lo),suffix_context:hi?a.slice(a.length-hi,a.length-hi+50):''}];}
