27	 const report='审查/F-revise-a-'+n+'重登核查.md';let text='# F修订A 第'+n+'章实读重登核查\n\n知情模型自检；非真人盲读或全尾段文学验收。完整正文展示与原journal精确增量核查后，由模型逐项填写。\n\n';
28	 for(const [k,v]of Object.entries(m.checked))text+='## '+k+'\n'+v+'\n\n';text+='## 真人语言别扭句\n### 真人语言硬问题\n'+m.language+'\n';
29	 fs.writeFileSync(path.join(b.project,report),text,{flag:'wx'});s.write('reports/'+n+'.md',text);
30	 for(const edit of m.input_edits||[]){let target=t;for(const k of edit.path.slice(0,-1))target=target[k];const key=edit.path.at(-1);if(edit.kind==='replace'){assert.equal(target[key].split(edit.before).length-1,1);target[key]=target[key].replace(edit.before,edit.after);}else{assert.equal(target[key],edit.before);target[key]=edit.after;}}
